html:
Here's my design direction: data engineers live in terminals, so I'm building this landing page as a "technical instrument" — warm near-black canvas, a single signal-orange accent, Instrument Serif for editorial headlines against JetBrains Mono for everything technical. The signature moment is a **working in-browser query console**: four preset SQL queries that actually execute over an in-memory dataset (real GROUP BY / window / time-travel computations in JS), rendering live result tables with inline bar charts and a mock execution plan. Plus a self-typing terminal in the hero, animated benchmarks, and an accordion of product principles — no card grids, no gradient decoration.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LODE — the open-source warehouse for data engineers</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=JetBrains+Mono:wght@400;500;700&family=Space+Grotesk:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root{
    --bg:#0B0B09; --bg2:#111110; --bg3:#161513;
    --line:#26241E; --line2:#3A382F;
    --ink:#E9E5DA; --mut:#98917F; --dim:#5C574A;
    --acc:#FF4D00; --acc-soft:#FF7A45;
    --serif:'Instrument Serif',serif;
    --mono:'JetBrains Mono',monospace;
    --sans:'Space Grotesk',sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased}
  ::selection{background:var(--acc);color:#0B0B09}
  a{color:inherit;text-decoration:none}
  button{font-family:inherit;cursor:pointer;background:none;border:none;color:inherit}
  :focus-visible{outline:1px solid var(--acc);outline-offset:3px}

  /* ---------- frame & ticks ---------- */
  .frame{max-width:1180px;margin:0 auto;border-left:1px solid var(--line);border-right:1px solid var(--line)}
  section.sec{position:relative;padding:96px clamp(24px,5vw,64px);scroll-margin-top:72px}
  section.sec::before,section.sec::after{
    content:'+';position:absolute;top:-11px;font-family:var(--mono);font-size:14px;color:var(--line2);line-height:1;z-index:2
  }
  section.sec::before{left:0;transform:translateX(-50%)}
  section.sec::after{right:0;transform:translateX(50%)}

  .k{font-family:var(--mono);font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--mut)}
  .k b{color:var(--acc);font-weight:500}

  /* ---------- nav ---------- */
  header{position:fixed;inset:0 0 auto 0;z-index:50;background:rgba(11,11,9,.84);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
  .nav-in{max-width:1180px;margin:0 auto;display:flex;align-items:center;gap:32px;padding:0 24px;height:60px}
  .wordmark{font-family:var(--serif);font-size:24px;letter-spacing:.06em;display:flex;align-items:center;gap:8px}
  .wordmark i{font-style:normal;color:var(--acc);font-size:14px;transform:translateY(-2px)}
  nav{margin-left:auto;display:flex;gap:28px}
  nav a{font-family:var(--mono);font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--mut);transition:color .2s}
  nav a:hover{color:var(--ink)}
  .ver{font-family:var(--mono);font-size:11px;color:var(--dim);border:1px solid var(--line);padding:3px 8px;border-radius:99px}
  .nav-gh{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:12px;color:var(--ink);border:1px solid var(--line);padding:7px 14px;border-radius:4px;transition:border-color .2s,color .2s}
  .nav-gh:hover{border-color:var(--acc);color:var(--acc)}
  @media(max-width:820px){nav a{display:none}}

  /* ---------- hero ---------- */
  .hero{padding-top:150px;padding-bottom:0;border-bottom:1px solid var(--line)}
  .hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center}
  h1{font-family:var(--serif);font-weight:400;font-size:clamp(52px,6.4vw,88px);line-height:.98;letter-spacing:-.01em;margin:22px 0 26px}
  h1 em{font-style:italic;color:var(--acc)}
  .lede{color:var(--mut);max-width:46ch;font-size:17px}
  .lede code{font-family:var(--mono);font-size:.86em;color:var(--ink);background:var(--bg3);padding:1px 6px;border-radius:3px;border:1px solid var(--line)}
  .cta-row{display:flex;gap:14px;margin-top:36px;flex-wrap:wrap;align-items:center}
  .btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--mono);font-size:13px;font-weight:500;letter-spacing:.04em;padding:14px 22px;border-radius:4px;transition:transform .15s,background .2s,border-color .2s}
  .btn-solid{background:var(--acc);color:#0B0B09}
  .btn-solid:hover{background:var(--acc-soft);transform:translateY(-1px)}
  .btn-solid svg{transition:transform .2s}
  .btn-solid:hover svg{transform:translate(2px,-2px)}
  .chip{display:inline-flex;align-items:center;gap:10px;font-family:var(--mono);font-size:12.5px;color:var(--mut);border:1px solid var(--line);padding:13px 16px;border-radius:4px;transition:border-color .2s,color .2s}
  .chip:hover{border-color:var(--line2);color:var(--ink)}
  .chip svg{opacity:.55}

  /* terminal */
  .term{background:var(--bg2);border:1px solid var(--line);border-radius:6px;overflow:hidden;box-shadow:0 24px 60px -30px rgba(0,0,0,.8)}
  .term-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);background:var(--bg3)}
  .dot{width:9px;height:9px;border-radius:50%;background:var(--line2)}
  .term-title{margin-left:8px;font-family:var(--mono);font-size:11px;color:var(--dim);letter-spacing:.08em}
  .live{margin-left:auto;display:flex;align-items:center;gap:6px;font-family:var(--mono);font-size:10px;color:var(--mut);letter-spacing:.12em}
  .live i{width:6px;height:6px;border-radius:50%;background:#5FA85F;animation:pulse 2s infinite}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
  .term-body{padding:18px;font-family:var(--mono);font-size:12.5px;line-height:1.75;min-height:262px;color:var(--ink);white-space:pre-wrap;word-break:break-word}
  .tl{color:var(--mut)}
  .tl.first{color:var(--ink)}
  .prompt{color:var(--acc)}
  .cursor{display:inline-block;width:7px;height:14px;background:var(--acc);vertical-align:-2px;animation:blink 1s steps(1) infinite}
  @keyframes blink{50%{opacity:0}}

  .stats{display:flex;border-top:1px solid var(--line);margin-top:88px}
  .stat{flex:1;padding:26px 28px 30px;border-left:1px solid var(--line)}
  .stat:first-child{border-left:none;padding-left:0}
  .stat b{display:block;font-family:var(--mono);font-weight:500;font-size:clamp(22px,2.4vw,30px);color:var(--ink)}
  .stat b s{text-decoration:none;color:var(--acc)}
  .stat span{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}

  /* ---------- ticker ---------- */
  .ticker{border-bottom:1px solid var(--line);overflow:hidden;padding:15px 0;background:var(--bg)}
  .tick-track{display:flex;width:max-content;gap:0;animation:tick 32s linear infinite}
  .ticker:hover .tick-track{animation-play-state:paused}
  @keyframes tick{to{transform:translateX(-50%)}}
  .tick-track span{font-family:var(--mono);font-size:11.5px;letter-spacing:.18em;color:var(--dim);padding:0 26px;white-space:nowrap}
  .tick-track span i{font-style:normal;color:var(--acc);padding-left:52px}

  /* ---------- principles ---------- */
  .sec-head{display:flex;align-items:baseline;gap:24px;margin-bottom:52px;flex-wrap:wrap}
  h2{font-family:var(--serif);font-weight:400;font-size:clamp(34px,4.4vw,54px);line-height:1.05;letter-spacing:-.01em}
  h2 em{font-style:italic;color:var(--acc)}
  .sec-head p{color:var(--mut);max-width:38ch;font-size:15px;margin-left:auto}

  .acc{border-top:1px solid var(--line)}
  .acc-item{border-bottom:1px solid var(--line)}
  .acc-head{width:100%;display:grid;grid-template-columns:80px 1fr 32px;align-items:center;gap:20px;padding:30px 4px;text-align:left;transition:padding .25s}
  .acc-head:hover{padding-left:14px}
  .acc-num{font-family:var(--mono);font-size:13px;color:var(--dim);transition:color .25s}
  .acc-item.open .acc-num,.acc-head:hover .acc-num{color:var(--acc)}
  .acc-title{font-family:var(--serif);font-size:clamp(22px,2.6vw,32px);line-height:1.15}
  .acc-arrow{justify-self:end;transition:transform .3s;color:var(--dim)}
  .acc-item.open .acc-arrow{transform:rotate(45deg);color:var(--acc)}
  .acc-panel{max-height:0;overflow:hidden;transition:max-height .45s cubic-bezier(.2,.7,.2,1)}
  .acc-body{display:grid;grid-template-columns:80px 1fr;gap:20px;padding:0 4px 34px}
  .acc-body p{color:var(--mut);max-width:58ch;font-size:15px}
  .acc-body code{display:inline-block;font-family:var(--mono);font-size:12px;color:var(--ink);background:var(--bg3);border:1px solid var(--line);padding:2px 8px;border-radius:3px;margin-top:14px}

  /* ---------- playground ---------- */
  #playground{background:var(--bg2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
  .pg-grid{display:grid;grid-template-columns:290px 1fr;gap:40px;align-items:start;margin-top:8px}
  .q-list{display:flex;flex-direction:column;border-top:1px solid var(--line)}
  .q-btn{text-align:left;border-bottom:1px solid var(--line);padding:18px 14px;transition:background .2s,padding .2s;position:relative}
  .q-btn:hover{background:var(--bg3);padding-left:20px}
  .q-btn .qn{font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--dim);display:block;margin-bottom:5px}
  .q-btn .qs{font-family:var(--mono);font-size:12px;color:var(--mut);line-height:1.5;display:block}
  .q-btn.active{background:var(--bg3)}
  .q-btn.active .qn{color:var(--acc)}
  .q-btn.active .qs{color:var(--ink)}
  .q-btn.active::before{content:'';position:absolute;left:0;top:-1px;bottom:-1px;width:2px;background:var(--acc)}

  .console{border:1px solid var(--line);border-radius:6px;background:var(--bg);overflow:hidden}
  .console-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);background:var(--bg3)}
  .run-btn{margin-left:auto;display:flex;align-items:center;gap:7px;font-family:var(--mono);font-size:11.5px;letter-spacing:.06em;color:#0B0B09;background:var(--acc);padding:6px 13px;border-radius:3px;font-weight:500;transition:background .2s}
  .run-btn:hover{background:var(--acc-soft)}
  .editor{padding:16px 18px;font-family:var(--mono);font-size:12.8px;line-height:1.7;min-height:132px;white-space:pre-wrap;color:var(--ink);outline:none;caret-color:var(--acc)}
  .editor:focus{background:var(--bg2)}
  .res-meta{display:flex;gap:16px;align-items:center;padding:9px 16px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--dim);background:var(--bg2)}
  .res-meta b{color:var(--acc);font-weight:500}
  .pg-lower{display:grid;grid-template-columns:1fr 250px;gap:0}
  .results{overflow-x:auto}
  table{width:100%;border-collapse:collapse;font-family:var(--mono);font-size:12px}
  th{text-align:left;font-weight:500;color:var(--dim);letter-spacing:.1em;text-transform:uppercase;font-size:10px;padding:11px 16px;border-bottom:1px solid var(--line);white-space:nowrap}
  td{padding:10px 16px;border-bottom:1px solid var(--line);color:var(--mut);white-space:nowrap}
  td:first-child,th:first-child{color:var(--ink)}
  tbody tr{transition:background .15s}
  tbody tr:hover{background:var(--bg2)}
  tbody tr:hover td{color:var(--ink)}
  .barcell{display:flex;align-items:center;gap:10px}
  .cb{display:inline-block;width:90px;height:5px;background:var(--bg3);border:1px solid var(--line);position:relative}
  .cb i{position:absolute;inset:0;right:auto;background:var(--acc)}
  .plan{border-left:1px solid var(--line);padding:14px 16px;font-family:var(--mono);font-size:11px;line-height:1.85;color:var(--dim);white-space:pre;overflow-x:auto}
  .plan b{color:var(--acc);font-weight:400}
  .res-foot{padding:10px 16px;font-family:var(--mono);font-size:11px;color:var(--dim)}
  .res-foot b{color:var(--ink);font-weight:400}
  .notice{padding:14px 18px;font-family:var(--mono);font-size:11.5px;color:var(--acc);border-top:1px solid var(--line);display:none;line-height:1.6}

  /* ---------- benchmarks ---------- */
  .bench-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;margin-top:8px}
  .bench h3{font-family:var(--mono);font-size:12px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin-bottom:28px}
  .bench h3 b{color:var(--ink)}
  .brow{display:grid;grid-template-columns:86px 1fr 70px;align-items:center;gap:14px;margin-bottom:20px}
  .bname{font-family:var(--mono);font-size:11.5px;color:var(--mut)}
  .brow.hero-row .bname{color:var(--ink)}
  .btrack{height:26px;border:1px solid var(--line);position:relative;background:var(--bg2)}
  .bfill{position:absolute;inset:2px auto 2px 2px;width:0;background:var(--dim);transition:width 1.2s cubic-bezier(.2,.7,.2,1)}
  .hero-row .bfill{background:var(--acc)}
  .bval{font-family:var(--mono);font-size:12px;color:var(--dim);text-align:right}
  .hero-row .bval{color:var(--acc)}
  .fineprint{font-family:var(--mono);font-size:10.5px;color:var(--dim);margin-top:20px;line-height:1.7}
  @media(max-width:820px){.bench-grid{grid-template-columns:1fr}}

  /* ---------- code section ---------- */
  #code{background:var(--bg2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
  .code-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:64px;align-items:start}
  .code-left{position:sticky;top:96px}
  .code-left p{color:var(--mut);font-size:15px;max-width:40ch;margin:20px 0 30px}
  .install{display:flex;align-items:center;gap:12px;border:1px solid var(--line);background:var(--bg);padding:14px 16px;border-radius:4px;font-family:var(--mono);font-size:12.5px;color:var(--ink)}
  .install span{color:var(--dim);margin-right:4px}
  .icopy{margin-left:auto;display:flex;color:var(--dim);padding:4px;transition:color .2s}
  .icopy:hover{color:var(--acc)}
  .codewin{border:1px solid var(--line);border-radius:6px;overflow:hidden;background:var(--bg)}
  .tabs{display:flex;border-bottom:1px solid var(--line);background:var(--bg3)}
  .tab{font-family:var(--mono);font-size:12px;color:var(--dim);padding:12px 18px;border-right:1px solid var(--line);transition:color .2s,background .2s}
  .tab:hover{color:var(--mut)}
  .tab.on{color:var(--ink);background:var(--bg);box-shadow:inset 0 -2px 0 var(--acc)}
  .codebox{display:none;padding:22px 24px;font-family:var(--mono);font-size:12.5px;line-height:1.85;overflow-x:auto;white-space:pre;color:var(--ink)}
  .codebox.on{display:block}
  .codebox .kw{color:var(--acc-soft)}
  .codebox .str{color:#D6C289}
  .codebox .cm{color:#6E695C}
  .codebox .num{color:#E0B15E}
  .codefoot{border-top:1px solid var(--line);padding:10px 18px;display:flex;align-items:center;font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim);background:var(--bg3)}
  .codefoot button{margin-left:auto;display:flex;align-items:center;gap:7px;font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--mut);transition:color .2s}
  .codefoot button:hover{color:var(--acc)}

  /* ---------- community ---------- */
  .comm{text-align:left;padding-top:110px;padding-bottom:110px}
  .comm h2{font-size:clamp(40px,5.4vw,68px);max-width:16ch}
  .comm p{color:var(--mut);max-width:52ch;margin:24px 0 36px}
  .comm-meta{display:flex;gap:36px;margin-top:52px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:28px}
  .comm-meta div{font-family:var(--mono);font-size:12px;color:var(--dim)}
  .comm-meta b{display:block;font-size:22px;font-weight:500;color:var(--ink)}
  .comm-meta b s{text-decoration:none;color:var(--acc)}

  /* ---------- footer ---------- */
  footer{border-top:1px solid var(--line)}
  .foot-grid{display:grid;grid-template-columns:1fr auto auto;gap:64px;padding:56px clamp(24px,5vw,64px)}
  .foot-grid h4{font-family:var(--mono);font-size:10.5px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--dim);margin-bottom:18px}
  .foot-grid a{display:block;font-family:var(--mono);font-size:12.5px;color:var(--mut);padding:5px 0;transition:color .2s}
  .foot-grid a:hover{color:var(--acc)}
  .foot-bottom{display:flex;align-items:center;gap:16px;padding:18px clamp(24px,5vw,64px);border-top:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--dim)}
  .foot-bottom .st{margin-left:auto;display:flex;align-items:center;gap:8px}
  .foot-bottom .st i{width:6px;height:6px;border-radius:50%;background:#5FA85F;animation:pulse 2s infinite}
  .giant{font-family:var(--serif);font-size:clamp(90px,19vw,250px);line-height:.9;letter-spacing:.02em;text-align:center;color:var(--bg3);-webkit-text-stroke:1px var(--line2);user-select:none;padding:40px 0 0;overflow:hidden}
  .giant i{font-style:normal;color:var(--acc);-webkit-text-stroke:0}

  /* ---------- toast ---------- */
  .toast{position:fixed;bottom:28px;left:50%;transform:translate(-50%,80px);background:var(--ink);color:#0B0B09;font-family:var(--mono);font-size:12px;padding:12px 20px;border-radius:4px;display:flex;align-items:center;gap:10px;opacity:0;transition:transform .35s cubic-bezier(.2,.7,.2,1),opacity .35s;z-index:99;pointer-events:none}
  .toast.show{transform:translate(-50%,0);opacity:1}
  .toast svg{color:var(--acc)}

  /* ---------- reveal ---------- */
  .rv{opacity:0;transform:translateY(20px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1)}
  .rv.in{opacity:1;transform:none}

  @media(max-width:960px){
    .hero-grid{grid-template-columns:1fr}
    .pg-grid{grid-template-columns:1fr}
    .q-list{flex-direction:row;overflow-x:auto;border-top:none;gap:10px}
    .q-btn{border:1px solid var(--line);border-radius:4px;min-width:220px}
    .q-btn.active::before{display:none}
    .code-grid{grid-template-columns:1fr}
    .code-left{position:static}
    .stats{flex-direction:column}
    .stat{border-left:none;border-top:1px solid var(--line);padding-left:0}
    .stat:first-child{border-top:none}
    .pg-lower{grid-template-columns:1fr}
    .plan{border-left:none;border-top:1px solid var(--line)}
    .foot-grid{grid-template-columns:1fr;gap:36px}
  }
  @media(prefers-reduced-motion:reduce){
    .tick-track{animation:none}
    .rv{opacity:1;transform:none;transition:none}
    .bfill{transition:none}
  }
</style>
</head>
<body>

