/* ---------- hero terminal: self-typing session ---------- */
const pad = (s,n)=> (s+' '.repeat(n)).slice(0,Math.max(n,s.length));
const TERM_SCRIPTS = [
  {
    q: "SELECT region, count(*), sum(revenue)\n  FROM events GROUP BY 1;",
