      [pad(' 9',5)+'|'+pad(' u_9911',8)+'|'+pad(' US-EAST',8)+'|'+pad(' 421.90',8)],
      [pad(' 7',5)+'|'+pad(' u_8123',8)+'|'+pad(' APAC',8)+'|'+pad(' 318.75',8)],
