const sleep = ms => new Promise(r=>setTimeout(r,ms));
function termLine(text, first){
  const d = document.createElement('div');
  d.className = 'tl' + (first ? ' first' : '');
  d.textContent = text;
  termBody.appendChild(d);
}
async function termLoop(){
  const body = $('#termbody');
  while(true){
    body.innerHTML = '';
    for(const sc of TERM_SCRIPTS){
      body.innerHTML = '';
      const prompt = document.createElement('div');
      prompt.className = 'tl first';
      prompt.innerHTML = '<span class="prompt">lode❯</span> ';
      const qSpan = document.createElement('span');
      const cur = document.createElement('span');
      cur.className = 'cursor';
      prompt.appendChild(qSpan); prompt.appendChild(cur);
      body.appendChild(prompt);
      if(REDUCED){ qSpan.textContent = sc.q; }
      else for(const ch of sc.q){ qSpan.textContent += ch; await sleep(26 + Math.random()*40); }
      await sleep(350);
      cur.remove();
      if(!REDUCED){ for(const r of sc.rows){ termLine(r[0]); if(r[1]) termLine(r[1]); await sleep(120);} }
      else sc.rows.forEach(r=>{ termLine(r[0]); if(r[1]) termLine(r[1]); });
      termLine(sc.foot);
      const next = document.createElement('div');
      next.innerHTML = '&nbsp;';
      body.appendChild(next);
      await sleep(3600);
    }
  }
}
termLoop();

