function groupSum(rows, keyFn, valFn){
  const m = new Map();
  rows.forEach(r=>{
    const k = keyFn(r);
    if(!m.has(k)) m.set(k, {key:k, n:0, sum:0});
    const g = m.get(k); g.n++; g.sum += valFn(r);
  });
  return [...m.values()];
}

const PRESETS = {
  p1: {
    sql:`SELECT region,
