    run(){
      const g = groupSum(EVENTS.filter(r=>r.status==='paid'), r=>r.region, r=>r.revenue)
        .sort((a,b)=>b.sum-a.sum);
      return {
        cols:[{label:'region',key:'key'},{label:'n',key:'n'},{label:'revenue',key:'sum',bar:true}],
        rows:g,
        plan:`└─ <b>HASH AGGREGATE</b> (group: region)
   ├─ <b>FILTER</b> status = 'paid'
   └─ <b>SEQ SCAN</b> events · ${EVENTS.length} rows`,
        eng:'engine: vectorized',
        tag:'scan · filter · hash aggregate'
      };
    }
  },
  p2: {
    sql:`SELECT user_id, region, revenue,
       rank() OVER (PARTITION BY region
                    ORDER BY revenue DESC) AS rk
FROM events
WHERE status = 'paid'
LIMIT 8;`,
    run(){
      const paid = EVENTS.filter(r=>r.status==='paid');
      const byRegion = {};
      paid.forEach(r=>{
        (byRegion[r.region] ??= []).push(r);
      });
      Object.values(byRegion).forEach(g=>g.sort((a,b)=>b.revenue-a.revenue));
      const rows = [];
      for(const [reg,g] of Object.entries(byRegion))
        g.forEach((r,i)=>rows.push({user:r.user, region:reg, revenue:r.revenue, rk:i+1}));
      rows.sort((a,b)=>b.revenue-a.revenue);
      return {
        cols:[{label:'user_id',key:'user'},{label:'region',key:'region'},
              {label:'revenue',key:'revenue',bar:true},{label:'rk',key:'rk'}],
        rows:rows.slice(0,8),
        plan:`└─ <b>WINDOW</b> rank() · part: region
   ├─ <b>SORT</b> revenue DESC
   ├─ <b>FILTER</b> status = 'paid'
   └─ <b>SEQ SCAN</b> events · ${EVENTS.length} rows`,
        eng:'engine: vectorized',
        tag:'scan · filter · sort · window'
      };
    }
  },
  p3: {
    sql:`SELECT date_trunc('day', ts) AS day,
       round(sum(revenue),2) AS revenue,
       bar(revenue, 0, 750)  AS trend
FROM events
GROUP BY day
ORDER BY day;`,
    run(){
      const g = groupSum(EVENTS, r=>r.ts.slice(0,10), r=>r.revenue)
        .sort((a,b)=>a.key.localeCompare(b.key));
      return {
        cols:[{label:'day',key:'key'},{label:'revenue',key:'sum',bar:true}],
        rows:g,
        plan:`└─ <b>HASH AGGREGATE</b> (group: date_trunc)
   ├─ <b>EXPR</b> bar(revenue, 0, 750)
   └─ <b>SEQ SCAN</b> events · ${EVENTS.length} rows`,
        eng:'engine: vectorized',
        tag:'scan · hash aggregate · expr'
      };
    }
  },
  p4: {
    sql:`SELECT id, user_id, region, status, revenue
FROM events AT TAG 'yesterday'
ORDER BY revenue DESC
LIMIT 5;`,
    run(){
      const rows = [...SNAP].sort((a,b)=>b.revenue-a.revenue).slice(0,5);
      return {
        cols:[{label:'id',key:'id'},{label:'user_id',key:'user'},{label:'region',key:'region'},
              {label:'status',key:'status'},{label:'revenue',key:'revenue',bar:true}],
        rows,
        plan:`└─ <b>SORT</b> revenue DESC · limit 5
   └─ <b>SNAPSHOT SCAN</b> events @ 'yesterday'
      └─ immutable tag · ${SNAP.length} rows`,
        eng:'engine: snapshot reader',
        tag:'snapshot scan · top-k'
      };
    }
  }
};

const editor = $('#editor'), results = $('#results'), planEl = $('#plan'),
      foot = $('#resfoot'), notice = $('#notice'), engTag = $('#engtag');
let currentP = 'p1';

const norm = s => s.replace(/\s+/g,' ').trim().replace(/;$/,'').trim();

function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }

function runQuery(pid, edited){
  const p = PRESETS[pid];
  const res = p.run();
  notice.style.display = 'none';

  const maxes = {};
  res.cols.forEach((c,ci)=>{ if(c.bar) maxes[ci] = Math.max(...res.rows.map(r=>r[c.key])); });

  let html = '<table><thead><tr>' + res.cols.map(c=>`<th>${c.label}</th>`).join('') + '</tr></thead><tbody>';
  res.rows.forEach(r=>{
    html += '<tr>' + res.cols.map((c,ci)=>{
      const v = r[c.key];
      if(c.bar){
        const w = maxes[ci] ? Math.max(2,(v/maxes[ci])*100) : 2;
        return `<td class="barcell"><span class="cb"><i style="width:${w}%"></i></span>${v.toFixed(2)}</td>`;
      }
      return `<td>${esc(typeof v === 'number' ? v : v)}</td>`;
    }).join('') + '</tr>';
  });
  html += '</tbody></table>';
  results.innerHTML = html;

  planEl.innerHTML = res.plan;
  engTag.textContent = res.eng;

  const ms = (res.rows.length * 0.031 + Math.random()*0.14 + 0.08).toFixed(2);
  foot.innerHTML = edited
    ? `edited query <b>matched Q${pid.slice(1)}</b> · <b>${res.rows.length} rows</b> · ${ms} ms · ${res.tag}`
    : `<b>${res.rows.length} rows</b> · ${ms} ms · ${res.tag}`;
}

function loadPreset(pid, viaClick){
  currentP = pid;
  editor.textContent = PRESETS[pid].sql;
  $$('.q-btn').forEach(b=>b.classList.toggle('active', b.dataset.p === pid));
  runQuery(pid, false);
  if(viaClick) editor.focus();
}

$$('.q-btn').forEach(b=>b.addEventListener('click', ()=>loadPreset(b.dataset.p, true)));

function attemptRun(){
  const q = norm(editor.innerText || '');
  for(const [pid,p] of Object.entries(PRESETS)){
    if(q === norm(p.sql)){ currentP = pid; runQuery(pid, true); return; }
  }
  notice.style.display = 'block';
  foot.innerHTML = `<b>0 rows</b> · query not recognized by the sandbox evaluator`;
}
$('#runbtn').addEventListener('click', attemptRun);
editor.addEventListener('keydown', e=>{
  if((e.metaKey || e.ctrlKey) && e.key === 'Enter'){ e.preventDefault(); attemptRun(); }
});
loadPreset('p1', false);

